toolScript:
const instructions = {
            'black': "Adjust <b>Brightness</b> until bar '2' is just barely visible, while bar '0' is perfect black.",
            'white': "Adjust <b>Contrast</b> until you can distinguish the separation between all bars (239-253).",
            'gamma': "Sit back and squint. Adjust <b>Gamma</b> until the solid squares blend into the striped background."
        };
        function setPattern(type) {
            // UI Update
            document.querySelectorAll('.cal-btn').forEach(b => b.classList.remove('active'));
            document.getElementById(`tab-${type}`).classList.add('active');
            // Show Pattern
            document.querySelectorAll('.pattern-overlay').forEach(p => p.classList.remove('active'));
            document.getElementById(`pat-${type}`).classList.add('active');
            // Text
            document.getElementById('hint-text').innerHTML = instructions[type];
        }
        function toggleFullScreen() {
            const el = document.getElementById('stage-container');
            if (!document.fullscreenElement) {
                el.requestFullscreen().catch(err => {
                    alert(`Error: ${err.message}`);
                });
            } else {
                document.exitFullscreen();
            }
        }
        // Initialize Scroll to Top logic
        document.addEventListener('DOMContentLoaded', () => {
            setPattern('black'); // Initial load
        });
